it('should mouse over Task 2 cell and expect async tooltip to show', () => {
  cy.get(`[style="top:${GRID_ROW_HEIGHT * 0}px"] > .slick-cell:nth(1)`).as('task1-cell');
  cy.get('@task1-cell').should('contain', 'Task 2');
