  await expect(page.getByRole('cell', { name: 'DISTRESS' })).toBeVisible();
  await expect(page.getByRole('cell', { name: 'CRITICAL' })).toBeVisible();
  await expect(page.getByRole('cell', { name: 'SEVERE' })).toBeVisible();

